/*
 * A346064  Number of primes that may be generated by changing any two digits
 *          of n simultaneously.
 * https://oeis.org/A346064
 *
 * Offset:    10    (a(10) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = number of distinct primes obtained by simultaneously
 *            changing any two digits of n, each changed digit must differ
 *            from the original. Non‑leading zeros are allowed (e.g. 02 is
 *            considered as 2)
 * Range:     u8 n <= 74, u16 n <= 74, u32 n <= 74, u64 n <= 74, u128 n <= 74,
 *            big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "../utils/is_prime.h"

seq_t a(idx_t n)
{
    /* compute decimal digits of n, most significant first */
    int d[20];          /* digits of n, msb first */
    int len = 0;
    idx_t tmp = n;
    int rev[20];
    while (tmp > 0) {
        rev[len++] = tmp % 10;
        tmp /= 10;
    }
    for (int i = 0; i < len; ++i)
        d[i] = rev[len - 1 - i];

    if (len < 2) return 0; /* offset starts at 10 */

    /* powers of 10 for each position */
    idx_t weight[20];
    weight[len - 1] = 1;
    for (int i = len - 2; i >= 0; --i)
        weight[i] = weight[i + 1] * 10;

    /* limit = 10^len, maximum candidate that can be forged */
    idx_t limit = weight[0] * 10;

    /* array to record which primes have been seen */
    char *seen = (char *)malloc((limit + 1) * sizeof(char));
    if (!seen) return 0;
    memset(seen, 0, (limit + 1) * sizeof(char));

    /* enumerate all pairs of positions */
    for (int i = 0; i < len - 1; ++i) {
        int di = d[i];
        for (int j = i + 1; j < len; ++j) {
            int dj = d[j];
            /* base value before changes at positions i and j */
            idx_t base = n - (idx_t)di * weight[i] - (idx_t)dj * weight[j];
            for (int a = 0; a < 10; ++a) {
                if (a == di) continue;              /* digit must change */
                for (int b = 0; b < 10; ++b) {
                    if (b == dj) continue;          /* digit must change */
                    idx_t cand = base + (idx_t)a * weight[i] + (idx_t)b * weight[j];
                    if (cand <= limit && is_prime(cand))
                        seen[cand] = 1;
                }
            }
        }
    }

    /* count distinct primes found */
    seq_t count = 0;
    for (idx_t v = 2; v <= limit; ++v)
        if (seen[v]) ++count;

    free(seen);
    return count;
}
